async function extractCurrent(auto=false){if(!project||busy)return false;if(auto&&project.entities.length)return true;if(project.entities.length&&!confirm('現在の図形を直線抽出結果に置き換えます。よろしいですか？'))return false;const len=Number($('length').value),threshold=Number($('ink-threshold').value);if(!Number.isInteger(len)||len<12||len>500){status('最短の線は12〜500画素で入力してください。');return false}busy=true;$('extract').disabled=true;status('画像から直線の候補を取り出しています…');try{const image=new Image();image.src=project.image;await image.decode();const c=document.createElement('canvas');c.width=project.width;c.height=project.height;const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(image,0,0);await new Promise(requestAnimationFrame);const pixels=ctx.getImageData(0,0,c.width,c.height).data;let entities=C.extract(pixels,c.width,c.height,{minLength:len,threshold,region});if(auto&&!entities.length)entities=C.extract(pixels,c.width,c.height,{minLength:len,threshold:Math.max(threshold,220),region});if(!entities.length){status('直線を取り出せませんでした。範囲や最短の線の設定を見直してください。既存の図形は変更していません。');return false}const raw=structuredClone(entities);if($('clean-auto').checked)entities=C.cleanLines(entities,{tolerance:Number($('clean-tolerance').value),bridge:C.inkBridge(pixels,c.width,c.height)});snapshot();project.rawExtraction=raw;project.entities=entities;selected.clear();$('clean-result').textContent='抽出 '+raw.length+'本 → 整理後 '+entities.length+'本。整理前にも戻せます。';render();status(entities.length+'本の直線候補を抽出しました。'+(raw.length-entities.length)+'本を重複・近接線として整理。すべて未分類です。原本と照合してください。');return true}catch(e){status('抽出できませんでした。範囲を狭めてお試しください。');return false}finally{busy=false;$('extract').disabled=false}}
