$('drawing').onclick=e=>{if(!project||busy||['box','lasso','pan','trace','freehand','rectangle','erase'].includes(mode))return;const pt=$('drawing').createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const p=pt.matrixTransform($('drawing').getScreenCTM().inverse());if(mode==='select'){const id=Number(e.target.dataset.id);if(id){selected.has(id)?selected.delete(id):selected.add(id);render()}return}points.push({x:Math.max(0,Math.min(project.width,p.x)),y:Math.max(0,Math.min(project.height,p.y))});if(points.length===2){const[a,rawB]=points,b=mode==='line'&&$('ortho').checked?C.orthogonalEnd(a,rawB):rawB;if(mode==='calibrate'){calibration=Math.hypot(b.x-a.x,b.y-a.y);if(calibration<2){calibration=null;status('離れた2点を指定してください。')}else status('寸法の実際の長さ（mm）を入力して「この寸法で縮尺を合わせる」を押してください。')}else if(mode==='crop'){region={x1:a.x,y1:a.y,x2:b.x,y2:b.y};if(Math.abs(a.x-b.x)<10||Math.abs(a.y-b.y)<10){region=null;status('範囲が小さすぎます。もう一度指定してください。')}else status('抽出範囲を指定しました。直線を抽出してください。')}else{if(project.entities.length>=24000){status('図形は24000個までです。');points=[];return}const distance=Math.hypot(a.x-b.x,a.y-b.y);if(distance>1){snapshot();project.entities.push({id:Math.max(0,...project.entities.map(e=>e.id))+1,type:mode==='line'?'line':'circle',layer:$('layer').value,x1:a.x,y1:a.y,...(mode==='line'?{x2:b.x,y2:b.y}:{r:distance})});status('図形を追加しました。')}}points=[]}render()};
