async function adoptWork(candidate,id=null){if(pdfTask)await pdfTask.destroy();pdfTask=null;invalidateExport();preparedJSON=null;$('save-file').hidden=true;$('save-result').textContent='';project=candidate;workId=id;boundary=candidate.focusBoundary||null;doc=null;guideIndex=null;history=[];region=null;calibration=null;points=[];selected.clear();$('page').replaceChildren(new Option((project.page||1)+'ページ',project.page||1));$('page').disabled=true;for(const n of ['crop','crop-clear','extract'])$(n).disabled=false;$('source').textContent=project.name+' / 保存作業';if(project.cropped){$('background').checked=true;$('opacity').value=Math.max(60,Number($('opacity').value))}dirty=false;if(window.CadWorkspace)$('background').checked=!project.entities.length;setMode('select');fit();}
$('save-local').onclick=async()=>{if(!project){localMessage('先に図面か作業JSONを開いてください。',true);return}if(busy){localMessage('処理が終わると自動保存します。少しお待ちください。');return}await saveLocalNow(true)};
$('work-open').onclick=async()=>{$('work-dialog').showModal();$('work-list').textContent='保存作業を確認しています…';try{const rows=await CadLocalStore.list();$('work-list').replaceChildren();if(!rows.length){$('work-list').textContent='まだ保存作業がありません。図面かJSONを開くと自動保存が始まります。';return}for(const row of rows){const b=document.createElement('button'),small=document.createElement('small');b.type='button';b.textContent=row.name;small.textContent=new Date(row.updatedAt).toLocaleString('ja-JP')+' · '+(row.page||1)+'ページ · 図形'+row.entities+'個'+(row.cropped?' · 切り出し済み':'');b.append(small);b.onclick=async()=>{if(busy)return;await saveLocalNow(true);if(!confirmDiscard())return;busy=true;try{const record=await CadLocalStore.get(row.id);if(!record)throw Error('保存作業が見つかりません。');const candidate=C.validate(record.project),image=new Image();image.src=candidate.image;await image.decode();if(image.width!==candidate.width||image.height!==candidate.height)throw Error('下図の大きさが一致しません。');await adoptWork(candidate,row.id);localRevision++;savedRevision=localRevision;dirty=false;$('work-dialog').close();localMessage('この端末の保存作業を開きました。編集後は自動保存します。');status('保存済みの下図・編集図形・レイヤー・縮尺を復元しました。')}catch(e){$('work-list').textContent='作業を開けません。'+e.message}finally{busy=false}};$('work-list').append(b)}}catch(e){$('work-list').textContent=e.message}};
$('work-close').onclick=()=>$('work-dialog').close();
$('save-share').onclick=async()=>{if(!preparedJSON)return;try{await navigator.share({files:[new File([preparedJSON.blob],preparedJSON.name,{type:'application/json'})],title:'図面の作業ファイル'});$('save-result').textContent='共有操作を終了しました。選んだ保存先を確認してください。'}catch(e){$('save-result').textContent=e.name==='AbortError'?'共有をキャンセルしました。端末内の自動保存は残っています。':'共有できませんでした。下のJSONダウンロードリンクを押してください。'}};
CadLocalStore.list().then(rows=>{if(!project)localMessage(rows.length?'この端末に保存作業が'+rows.length+'件あります。「この端末の作業を開く」で再開できます。':'編集後はこの端末に自動保存します。JSONファイルでもバックアップできます。')}).catch(()=>{if(!project)localMessage('端末内の保存領域を使えません。通常のSafariで開くか、JSONファイルへ保存してください。',true)});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&project&&dirty)saveLocalNow(true).catch(()=>{})});

$('clean-current').onclick=async()=>{if(!project||busy)return;if(!project.entities.length){status('先に画像から線を抽出してください。');return}busy=true;try{const image=new Image();image.src=project.image;await image.decode();const c=document.createElement('canvas');c.width=project.width;c.height=project.height;const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(image,0,0);const before=project.entities.length,cleaned=C.cleanLines(project.entities,{tolerance:Number($('clean-tolerance').value),bridge:C.inkBridge(ctx.getImageData(0,0,c.width,c.height).data,c.width,c.height)});snapshot();if(!project.rawExtraction)project.rawExtraction=structuredClone(project.entities);project.entities=cleaned;selected.clear();$('clean-result').textContent=before+'本 → '+cleaned.length+'本。分類済みの線・円は変更していません。';render();status('未分類の直線を整理しました。原本と比較し、必要なら「ひとつ戻す」で戻せます。')}catch(e){status('線を整理できませんでした。現在の図形は保持しています。')}finally{busy=false}};
$('clean-restore').onclick=()=>{if(!project?.rawExtraction?.length||busy)return;if(!confirm('抽出時の整理前の線へ戻します。その後の加筆・削除・分類も戻ります。よろしいですか？'))return;const raw=structuredClone(project.rawExtraction);snapshot();project.entities=raw;selected.clear();$('clean-result').textContent='整理前の '+raw.length+'本へ戻しました。「ひとつ戻す」で直前の編集状態にも戻せます。';render()};

$('uniform-color').onchange=()=>{invalidateExport();render()};
$('square-selection').onclick=()=>{if(!project||busy||!selected.size){status('一つの器具の輪郭線だけを選択してください。');return}const lines=project.entities.filter(e=>selected.has(e.id));if(lines.some(e=>e.type!=='line')||new Set(lines.map(e=>e.layer)).size!==1){status('同じレイヤーの直線だけを選択してください。円は四角に変更しません。');return}const xs=lines.flatMap(e=>[e.x1,e.x2]),ys=lines.flatMap(e=>[e.y1,e.y2]);const rect=C.rectangleLines({x:Math.min(...xs),y:Math.min(...ys)},{x:Math.max(...xs),y:Math.max(...ys)},lines[0].layer);if(!rect.length){status('幅と高さのある輪郭を選択してください。');return}if(project.entities.length-lines.length+4>24000){status('図形は24000個までです。');return}snapshot();project.entities=project.entities.filter(e=>!selected.has(e.id));let id=Math.max(0,...project.entities.map(e=>e.id));for(const line of rect)project.entities.push({...line,id:++id});selected=new Set(rect.map((_,i)=>id-3+i));render();status('選択した輪郭を一つの四角に整えました。位置・形は元図と照合してください。「ひとつ戻す」で取り消せます。')};

