const toolInfo={select:{title:'選択',action:'線・円・文字を1回タップすると赤く選ばれます。もう1回タップすると、その線の選択を外します。',use:'選んだ後は、削除・四角に整える・レイヤーへの仕分けができます。'},box:{title:'四角選択',action:'Pencilで対角へドラッグして囲み、離します。囲みに触れたCAD線・円が赤く選ばれます。',use:'まとめて選ぶ時や、下図を切り出す範囲を決める時に使います。'},lasso:{title:'投げ縄',action:'Pencilで自由な形に囲み、離します。囲みに触れたCAD線・円を選びます。',use:'四角では囲みにくい器具や、一部分だけを選ぶ時に使います。'},trace:{title:'直線',action:'始点から終点へなぞり、Pencilを離すと一本の直線になります。',use:'水平・垂直補正は左側で切り替えます。斜めに描く時は補正をオフにします。'},rectangle:{title:'四角',action:'四角の一つの角から対角へドラッグして離すと、直角の4辺を描きます。',use:'四角い器具などを追加する時に使います。「四角選択」は囲んで選ぶ道具で、この「四角」は線を描く道具です。'},freehand:{title:'自由線',action:'Pencilでなぞった形を、短い直線のつながりとして描きます。',use:'曲がった形を補う時に使います。きれいな四角は「四角」、円は左側の「円を2点で追加」を使います。'},erase:{title:'消しゴム',action:'消したいCAD線や円をなぞり、離すと触れた図形を丸ごと消します。',use:'線の一部分だけを切り取る消去ではありません。左側で太さを選び、間違えたら「ひとつ戻す」で復元します。'},pan:{title:'移動',action:'ドラッグして、図面を見る位置を変えます。線そのものの位置は変わりません。',use:'拡大した図面の別の場所を見たい時に使います。2本指で拡大・縮小もできます。'}};
