function updateOperationHelp(){const info=toolInfo[mode];$('mode-instruction').textContent=info?info.action:({line:'図面上で始点・終点を順にタップすると直線を追加します。',circle:'中心をタップし、次に円周になる位置をタップします。',crop:'抽出したい範囲の対角へドラッグします。枠の内側から線を抽出します。',calibrate:'元図の寸法が分かる2点を順にタップし、左側に実際の長さ（mm）を入力します。'})[mode]||'';$('selection-guidance').textContent=!project?'まず上部の「図面を開く」で資料を選んでください。':!project.entities.length?'現在は下図の画像だけです。CAD線はまだ0個なので、「水平・垂直の線を抽出」するか、線を描き足すと選択できます。':selected.size?'赤い '+selected.size+'個のCAD図形を選択中です。「設定・レイヤー」で仕分け先を選ぶか、左側で削除・四角化ができます。':'CAD線・円・文字をタップするか、範囲を囲んで選択してください。選択された線は赤くなります。';if(project&&!loadGuideClosed){$('load-guide').open=false;loadGuideClosed=true}}
for(const [key,info]of Object.entries(toolInfo)){const card=document.createElement('div'),h=document.createElement('h3'),p=document.createElement('p'),use=document.createElement('p'),button=document.createElement('button');h.textContent=info.title;p.textContent=info.action;use.textContent=info.use;button.textContent='この道具を使う';button.dataset.helpMode=key;button.setAttribute('aria-label',info.title+'を使う');button.onclick=()=>{$('tools-dialog').close();setMode(key);window.CadWorkspace?.hide();$('tool-state').scrollIntoView({block:'center',behavior:'smooth'})};card.append(h,p,use,button);$('tool-explanations').append(card)}
$('tools-help').onclick=()=>$('tools-dialog').showModal();$('tools-close').onclick=()=>$('tools-dialog').close();
