$('open-source-shortcut').onclick=()=>$('pdf').click();$('open-json-shortcut').onclick=()=>$('project-file').click();$('open-local-shortcut').onclick=()=>$('work-open').click();updateOperationHelp();
const UPDATE_RESUME='pdf-cad-draft.resume-after-update.v1';
$('check-update').onclick=async()=>{const b=$('check-update'),main=document.querySelector('main');let locked=false,navigating=false;if(busy||penId!==null||pointers.size){$('update-status').textContent='読み込み・描画が終わってから、もう一度「更新を確認」を押してください。';return}b.disabled=true;try{$('update-status').textContent='新しい版を確認しています…';const response=await fetch(new URL('version.json?at='+Date.now(),location.href),{cache:'no-store'});if(!response.ok)throw Error('network');const next=await response.json(),current=document.querySelector('meta[name="cad-version"]')?.content;if(!/^[a-f0-9]{12}$/.test(next.version))throw Error('version');if(next.version===current){$('update-status').textContent='最新版です。資料の開き方は「資料の読み込み方法」、道具の説明は図面上の「道具の使い方を見る」から確認できます。';return}if(busy||penId!==null||pointers.size){$('update-status').textContent='確認中に読み込み・描画が始まったため、更新は行っていません。操作が終わってから、もう一度押してください。';return}busy=true;locked=true;main.inert=true;if(project){if(!await saveLocalNow(true)){$('update-status').textContent='現在の作業を端末に保存できないため、更新は行っていません。先に「ファイルにも保存（JSON）」で控えを保存してください。';return}sessionStorage.setItem(UPDATE_RESUME,JSON.stringify({id:workId}));}const url=new URL(location.href);url.searchParams.set('v',next.version);$('update-status').textContent=project?'現在のページを保存しました。新しい版を読み込み、現在のページを再開します。':'新しい版を読み込んでいます。';navigating=true;location.replace(url.href)}catch(e){navigating=false;$('update-status').textContent='更新を確認できませんでした。通信やブラウザの保存設定を確認してください。現在の画面はそのまま使えます。'}finally{if(locked&&!navigating){busy=false;main.inert=false}b.disabled=navigating}};
async function resumeUpdatedWork(){let marker;try{marker=JSON.parse(sessionStorage.getItem(UPDATE_RESUME)||'null');if(!marker)return;sessionStorage.removeItem(UPDATE_RESUME);if(typeof marker.id!=='string')return;busy=true;const row=await CadLocalStore.get(marker.id);if(!row)throw Error();const candidate=C.validate(row.project),image=new Image();image.src=candidate.image;await image.decode();if(image.width!==candidate.width||image.height!==candidate.height)throw Error();await adoptWork(candidate,marker.id);localRevision++;savedRevision=localRevision;dirty=false;localMessage('更新前の作業を端末内の保存から再開しました。');$('update-status').textContent='更新しました。直前のページの編集を再開しています。別ページを見る時は「図面を開く」から原本を選び直してください。';status('更新前の下図・編集線・仕分け・縮尺を復元しました。ひとつ戻す履歴は新しくなります。')}catch(e){$('update-status').textContent='更新しました。保存した作業は「この端末の作業を開く」から選んで再開してください。'}finally{busy=false}}
resumeUpdatedWork();

function updateVectorAvailability(){const ready=!!(project&&doc?.getPage&&!project.cropped&&typeof doc.getData==='function');$('extract-vector').disabled=!ready;$('import-text').disabled=!ready;$('text-source-file').disabled=!project||!!project.cropped;$('text-source-state').textContent=ready?'原本PDFの現在ページから文字を取り込めます。':project?.cropped?'切り出し済みです。原本PDFで文字を取り込んでから切り出してください。':'保存作業だけでは元の文字データがありません。下から同じ原本PDFを接続すると、今の図形を残して文字を追加できます。';$('vector-availability').textContent=ready?'現在ページが対象です。範囲を指定していなければページ全体から取り込みます。':'原本PDFを開いた現在ページで使えます。保存作業・切り出し後・TIFF等は画像から抽出してください。';$('extract-vector').title=ready?'現在ページの元の描線を候補として取り込みます':'原本PDFを開いた現在ページで使えます。保存作業・切り出し後・TIFF等は画像から抽出してください。';}
async function extractPDFCurrent(auto=false){if(!project||!doc||busy||project.cropped)return false;if(auto&&project.entities.length)return true;if(!auto&&project.entities.length&&!confirm('現在の線・円・文字を、PDFの取り込み結果に置き換えます。必要なら先にJSONで保存してください。置き換えますか？'))return false;busy=true;$('extract-vector').disabled=true;status('PDFの元の線データを確認しています…');try{const page=await doc.getPage(project.page);if(typeof page.getOperatorList!=='function')throw Error('画像形式です。「水平・垂直の線を抽出」をお使いください。');const base=page.getViewport({scale:1}),viewport=page.getViewport({scale:Math.min(project.width/base.width,project.height/base.height)}),list=await page.getOperatorList(),result=CadPDFVectors.extract(list,pdfjs.OPS,viewport,{width:project.width,height:project.height,region,core:C});if($('include-text').checked){const tx=CadPDFText.extract(await page.getTextContent(),viewport,{width:project.width,height:project.height,region,core:C});result.textCount=tx.entities.length;result.textSkipped=tx.skipped;result.entities.push(...tx.entities);result.entities=result.entities.map((e,i)=>({...e,id:i+1}));if(result.entities.length>24000)throw Error('線と文字の合計が24000個を超えます。範囲を絞ってください。');}if(!result.entities.length){$('vector-result').textContent='取り込める元の描線がありませんでした。画像だけのPDF、または未対応の形式の可能性があります。「水平・垂直の線を抽出」をお試しください。既存の図形は残しています。';status($('vector-result').textContent);return false}snapshot();project.entities=result.entities;project.rawExtraction=null;if(window.CadWorkspace)$('background').checked=false;selected.clear();visible.add('review');document.querySelector('[data-visible="review"]').checked=true;$('clean-result').textContent='元の線から取り込みました。画素による近接線の整理は行っていません。';$('vector-result').textContent=(result.entities.length-(result.textCount||0))+'本の線候補'+(result.textCount?'と'+result.textCount+'件の文字':'')+'を取り込みました。斜線・短い線を含み、曲線は折れ線です。'+(result.skipped?result.skipped+'個の特殊な描線は取り込めませんでした。':'')+''+(result.textCount?'文字も取り込み済みです。':'文字を取り込むには「文字」パネルを開いてください。')+'塗りつぶし・画像は下図に残ります。原本と照合してください。線は未分類なので、照明器具を選んで「照明へ」で仕分けできます。';render();status($('vector-result').textContent);return true;}catch(e){$('vector-result').textContent='取り込めませんでした。'+e.message+' 既存の図形は残しています。';status($('vector-result').textContent);if(auto)throw Error($('vector-result').textContent);return false}finally{busy=false;updateVectorAvailability()}}
$('extract-vector').onclick=()=>extractPDFCurrent(false);
$('reopen-vector-source').onclick=()=>$('pdf').click();
$('source-clear').onclick=()=>{$('background').checked=true;$('opacity').value='100';$('lighting-focus').checked=false;render();status('原本全体をはっきり表示しています。文字・器具も下図に含まれています。編集線・DXFは変更していません。')};
$('lighting-focus').onchange=()=>{if($('lighting-focus').checked){visible.add('lighting');const box=document.querySelector('[data-visible="lighting"]');if(box)box.checked=true;}render();status($('lighting-focus').checked?(project?.entities.some(e=>e.layer==='lighting')?'照明の線を明るく太く表示しています。表示だけの変更です。':'まだ照明に仕分けた線がありません。器具の線を選択し「照明へ」で仕分けてください。'):'通常の表示に戻しました。')};

function updateTextEditor(){const e=selected.size===1?project?.entities.find(e=>selected.has(e.id)&&e.type==='text'):null;for(const id of ['text-value','text-height','apply-text'])$(id).disabled=!e;$('text-value').value=e?.text||'';$('text-height').value=e?.height||'';}
$('apply-text').onclick=()=>{const e=selected.size===1?project?.entities.find(e=>selected.has(e.id)&&e.type==='text'):null;if(!e||busy)return;const text=$('text-value').value,height=Number($('text-height').value);try{const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');ctx.font=e.height+'px sans-serif';const ratio=ctx.measureText(text).width/Math.max(.001,ctx.measureText(e.text).width),changed={...e,text,height,width:e.width*ratio*height/e.height};C.validate({...project,entities:[changed]});snapshot();Object.assign(e,changed);render();status('選んだ文字を変更しました。作業JSONと文字ありのDXFに反映します。')}catch(err){status(err.message)}};
$('import-text').onclick=async()=>{if(!project||!doc||busy||project.cropped)return;if(project.entities.some(e=>e.type==='text')&&!confirm('既存の文字を原本PDFから取り直します。線・円は残します。よろしいですか？'))return;busy=true;try{const page=await doc.getPage(project.page),base=page.getViewport({scale:1}),viewport=page.getViewport({scale:Math.min(project.width/base.width,project.height/base.height)}),tx=CadPDFText.extract(await page.getTextContent(),viewport,{width:project.width,height:project.height,region,core:C});if(!tx.entities.length){$('text-result').textContent='取り込める文字データがありません。画像の文字や縦書きは対象外です。既存の文字は残しています。';status($('text-result').textContent);return}const keep=project.entities.filter(e=>e.type!=='text');if(keep.length+tx.entities.length>24000)throw Error('線と文字の合計が24000個を超えます。範囲を絞ってください。');snapshot();project.entities=[...keep,...tx.entities].map((e,i)=>({...e,id:i+1}));selected.clear();visible.add('text');document.querySelector('[data-visible="text"]').checked=true;$('text-result').textContent=tx.entities.length+'件の文字を取り込みました。'+(tx.skipped?tx.skipped+'件は範囲外または未対応のため除外。':'')+'文字レイヤーで表示を切り替えられます。';render();status($('text-result').textContent)}catch(err){status('文字を取り込めませんでした。'+err.message)}finally{busy=false;updateVectorAvailability()}};
window.addEventListener('cad-workspace-fit',fit);

$('text-source-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(!project||busy||project.cropped){e.target.value='';return}let loading;try{if(file.size>80000000)throw Error('PDFは80MB以内を選んでください。');busy=true;await saveLocalNow(true);loading=pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),cMapUrl:new URL('./vendor/pdfjs/cmaps/',import.meta.url).href,cMapPacked:true,standardFontDataUrl:new URL('./vendor/pdfjs/standard_fonts/',import.meta.url).href,wasmUrl:new URL('./vendor/pdfjs/wasm/',import.meta.url).href,isEvalSupported:false});const next=await loading.promise;if(next.numPages>200||project.page>next.numPages)throw Error('保存作業とPDFのページ数が一致しません。');if(project.pdfFingerprint&&next.fingerprints?.[0]!==project.pdfFingerprint)throw Error('作業とは別のPDFです。同じ原本PDFを選んでください。');const page=await next.getPage(project.page),v=page.getViewport({scale:1});if(Math.abs((v.width/v.height)/(project.width/project.height)-1)>.005)throw Error('保存作業とPDFの縦横比が違います。同じ原本PDFを選んでください。');const previous=pdfTask;doc=next;pdfTask=loading;loading=null;sourceName=file.name;project.pdfFingerprint=next.fingerprints?.[0]||null;markForSave();if(previous)try{await previous.destroy()}catch(_){}$('page').replaceChildren(new Option(project.page+'ページ（接続中）',project.page));$('page').disabled=true;$('source').textContent=file.name+' / '+project.page+'ページ（原本接続・編集保持）';render();status('原本PDFを接続しました。今の下図・編集線・文字は残しています。「PDFの文字だけ取り込む・更新」を押してください。')}catch(err){if(loading)await loading.destroy();status('原本PDFを接続できませんでした。'+err.message+' 今の作業は残しています。')}finally{busy=false;e.target.value='';updateVectorAvailability()}};
